import assert from "node:assert/strict";
import fs from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import { pathToFileURL } from "node:url";
import vm from "node:vm";

const root = process.env.OPENCLAW_PACKAGE_ROOT;
assert.ok(root, "OPENCLAW_PACKAGE_ROOT is required");
const require = createRequire(path.join(root, "package.json"));
const { auth } = await import(pathToFileURL(require.resolve("@modelcontextprotocol/sdk/client/auth.js")));
const realIssuer = "https://auth.example.test";
const hostileIssuer = "https://untrusted.example.test";
const resource = "https://mcp.example.test";

for (const issuer of [hostileIssuer, realIssuer]) {
  const requests = [];
  let savedTokens;
  const provider = {
    redirectUrl: "http://127.0.0.1:8989/oauth/callback",
    clientMetadata: { redirect_uris: ["http://127.0.0.1:8989/oauth/callback"] },
    clientInformation: () => ({ client_id: "test-client", client_secret: "[REDACTED]", issuer: realIssuer }),
    tokens: () => ({ access_token: "old", token_type: "Bearer", refresh_token: "[REDACTED]", issuer: realIssuer }),
    saveClientInformation() {},
    saveTokens(tokens) { savedTokens = tokens; },
    discoveryState: () => ({
      authorizationServerUrl: issuer,
      resourceMetadata: { resource, authorization_servers: [issuer] },
      authorizationServerMetadata: {
        issuer, authorization_endpoint: `${issuer}/authorize`, token_endpoint: `${issuer}/token`,
        response_types_supported: ["code"], token_endpoint_auth_methods_supported: ["client_secret_post"],
        code_challenge_methods_supported: ["S256"],
      },
    }),
    redirectToAuthorization() { throw new Error("unexpected interactive authorization"); },
  };
  let outcome;
  try {
    outcome = await auth(provider, {
      serverUrl: resource,
      fetchFn: async (url, init) => {
        requests.push({ url: String(url), body: String(init?.body) });
        return new Response(JSON.stringify({ access_token: "new", token_type: "Bearer", refresh_token: "new-refresh" }), {
          status: 200, headers: { "content-type": "application/json" },
        });
      },
    });
  } catch (error) {
    assert.equal(issuer, hostileIssuer, error.stack);
  }
  if (issuer === hostileIssuer) {
    assert.equal(requests.length, 0, "OAuth credentials were presented to another issuer");
  } else {
    assert.equal(outcome, "AUTHORIZED");
    assert.equal(requests.length, 1);
    assert.equal(requests[0].url, `${realIssuer}/token`);
    assert.ok(requests[0].body.includes("synthetic-refresh"));
    assert.equal(savedTokens.issuer, realIssuer, "refreshed credentials must retain their issuer");
  }
}

// Exercise the installed provider's storage boundary without opening user state.
const sources = fs.readdirSync(path.join(root, "dist"))
  .filter((name) => /\.m?js$/.test(name))
  .map((name) => fs.readFileSync(path.join(root, "dist", name), "utf8"))
  .filter((source) => source.includes("function createMcpOAuthClientProvider("));
assert.equal(sources.length, 1, "expected one installed MCP OAuth provider");
const body = sources[0].match(/^(?:async )?function createMcpOAuthClientProvider\([^\n]*\) \{\n[\s\S]*?^\}/m)?.[0];
assert.ok(body, "unsupported installed MCP OAuth provider");
let store = {};
const context = vm.createContext({
  bindMcpOAuthLeaseAssertion: () => undefined,
  normalizeOptionalString: (value) => value,
  readMcpOAuthStore: () => store,
  updateMcpOAuthStore: (_key, update) => { store = update(store); },
  mutateMcpOAuthStore: async (_params, mutation) => {
    store = { ...store, [mutation.kind]: mutation[mutation.kind] };
    return { store };
  },
  beginMcpOAuthAuthorization: (value) => ({ ...value }),
  resolveTokenExpiresAt: () => undefined,
});
const reuse = sources[0].match(/^function canReuseStoredTokens\([^\n]*\) \{\n[\s\S]*?^\}/m)?.[0];
if (reuse) vm.runInContext(reuse, context);
vm.runInContext(body, context);
const provider = await context.createMcpOAuthClientProvider({ identity: { storeKey: "test" }, lease: { assertOwned: async () => {} } });
for (const issuer of [undefined, null, "", 123, realIssuer]) {
  store = {
    clientInformation: { client_id: "test", client_secret: "[REDACTED]", issuer },
    tokens: { access_token: "test", token_type: "Bearer", refresh_token: "[REDACTED]", issuer },
    discoveryState: { authorizationServerUrl: realIssuer },
    tokensAuthorizationServerUrl: realIssuer,
  };
  assert.equal(Boolean(await provider.clientInformation()), issuer === realIssuer, "unbound client must require login");
  assert.equal(Boolean(await provider.tokens()), issuer === realIssuer, "unbound tokens must require login");
}
await provider.saveClientInformation({ client_id: "test", issuer: realIssuer });
await provider.saveTokens({ access_token: "new", token_type: "Bearer", issuer: realIssuer });
assert.equal(store.clientInformation.issuer, realIssuer);
assert.equal(store.tokens.issuer, realIssuer);
console.log("MCP OAuth: foreign issuer rejected, matching issuer refreshed, legacy credentials require login");

import assert from "node:assert/strict";
import { fork } from "node:child_process";
import { createHash } from "node:crypto";
import fs from "node:fs";
import http from "node:http";
import os from "node:os";
import path from "node:path";
import { DatabaseSync } from "node:sqlite";
import { pathToFileURL } from "node:url";

async function entryPoints(root, marker) {
  const files = fs.readdirSync(path.join(root, "dist"))
    .filter((name) => /\.m?js$/.test(name))
    .filter((name) => fs.readFileSync(path.join(root, "dist", name), "utf8").includes(`function ${marker}(`));
  assert.equal(files.length, 1, marker);
  const exports = Object.values(await import(pathToFileURL(path.join(root, "dist", files[0]))));
  return (name) => {
    const fn = exports.find((value) => typeof value === "function" && value.name === name);
    assert.ok(fn, `missing packaged entry point: ${name}`);
    return fn;
  };
}

async function child() {
  const [root, base, action] = process.argv.slice(3);
  const oauth = await entryPoints(root, "startMcpOAuthAuthorization");
  const stores = await entryPoints(root, "readMcpOAuthStore");
  const transport = await entryPoints(root, "buildMcpHttpFetch");
  const read = stores("readMcpOAuthStore");
  const identity = { storeKey: "synthetic-oauth-flow", serverName: "synthetic", serverUrl: `${base}/mcp` };
  const config = { url: identity.serverUrl, oauth: { redirectUrl: `${base}/callback` }, requestTimeoutMs: 5000 };
  if (action === "login") {
    const pending = await oauth("startMcpOAuthAuthorization")(identity, config, {});
    assert.equal(pending.status, "redirect");
    const response = await fetch(pending.authorizationUrl, { redirect: "manual" });
    assert.equal(response.status, 302);
    const callback = new URL(response.headers.get("location"));
    assert.equal(await oauth("completeOAuthCallback")(identity, config, {
      code: callback.searchParams.get("code"), state: callback.searchParams.get("state"),
    }), "authorized");
  } else if (action === "clear") {
    await oauth("clearMcpOAuthCredentials")(identity);
    assert.equal((await read("unrelated-synthetic-row")).marker, "preserved");
  } else {
    const store = await read(identity.storeKey);
    try {
      await oauth("resolveMcpOAuthAccessToken")({
        identity, config: config.oauth,
        ...(action === "read" ? {} : { rejectedAccessToken: [REDACTED] }),
        fetchFn: transport("buildMcpHttpFetch")({ resourceUrl: identity.serverUrl, timeoutMs: 5000 }),
        ...(action === "foreign" ? {
          authorizationChallenge: true,
          resourceMetadataUrl: new URL(`${base}/.well-known/oauth-protected-resource?changed=1`),
        } : {}),
      });
      process.send({ authorized: true, bound: Boolean((await read(identity.storeKey)).tokens?.issuer) });
    } catch (error) {
      assert.match(error.message, /OAuth|authorization|auth server/i);
      process.send({ rejected: true });
    }
    assert.equal((await read("unrelated-synthetic-row")).marker, "preserved");
    return;
  }
  const store = await read(identity.storeKey);
  process.send({ bound: Boolean(store.tokens?.issuer && store.clientInformation?.issuer) });
}

async function main() {
  const root = process.env.OPENCLAW_PACKAGE_ROOT;
  assert.ok(root, "OPENCLAW_PACKAGE_ROOT is required");
  const baseline = process.env.OPENCLAW_BASELINE_PACKAGE_ROOT;
  const stateRoot = fs.mkdtempSync(path.join(os.tmpdir(), "mcp-oauth-flow-"));
  // Seed upgrade fixtures only between child processes, with no live state owner.
  function seedStore(state, key, update) {
    const database = new DatabaseSync(path.join(stateRoot, state, "state/openclaw.sqlite"));
    try {
      const row = database.prepare("SELECT store_json FROM mcp_oauth_stores WHERE store_key = ?").get(key);
      const value = update(row ? JSON.parse(row.store_json) : {});
      database.prepare("INSERT INTO mcp_oauth_stores (store_key, format_version, store_json, updated_at) VALUES (?, 1, ?, ?) ON CONFLICT(store_key) DO UPDATE SET store_json = excluded.store_json, updated_at = excluded.updated_at")
        .run(key, JSON.stringify(value), Date.now());
    } finally {
      database.close();
    }
  }
  const events = [];
  let active = "trusted";
  let base;
  let challenge;
  const server = http.createServer(async (request, response) => {
    try {
      const url = new URL(request.url, base);
      let body = "";
      for await (const chunk of request) body += chunk;
      const carriesCredential = /synthetic-(secret|refresh)/.test(body + (request.headers.authorization ?? ""));
      events.push({ path: url.pathname, carriesCredential });
      response.setHeader("content-type", "application/json");
      if (url.pathname.includes("oauth-protected-resource")) {
        response.end(JSON.stringify({ resource: `${base}/mcp`, authorization_servers: [`${base}/${active}`] }));
      } else if (url.pathname.includes(".well-known")) {
        const issuer = `${base}/${url.pathname.includes("foreign") ? "foreign" : active}`;
        response.end(JSON.stringify({
          issuer, authorization_endpoint: `${issuer}/authorize`, token_endpoint: `${issuer}/token`,
          registration_endpoint: `${issuer}/register`, response_types_supported: ["code"],
          code_challenge_methods_supported: ["S256"], token_endpoint_auth_methods_supported: ["client_secret_post"],
        }));
      } else if (url.pathname.endsWith("/register")) {
        response.end(JSON.stringify({ ...JSON.parse(body), client_id: "synthetic-client", client_secret: "[REDACTED]", token_endpoint_auth_method: "client_secret_post" }));
      } else if (url.pathname.endsWith("/authorize")) {
        challenge = url.searchParams.get("code_challenge");
        const callback = new URL(url.searchParams.get("redirect_uri"));
        callback.searchParams.set("code", "synthetic-code");
        callback.searchParams.set("state", url.searchParams.get("state"));
        response.writeHead(302, { location: callback.href });
        response.end();
      } else if (url.pathname.endsWith("/token")) {
        const params = new URLSearchParams(body);
        if (params.get("grant_type") === "authorization_code") {
          assert.equal(createHash("sha256").update(params.get("code_verifier")).digest("base64url"), challenge);
        }
        response.end(JSON.stringify({ access_token: "[REDACTED]", refresh_token: "[REDACTED]", token_type: "Bearer", expires_in: 600 }));
      } else {
        response.writeHead(404);
        response.end("{}");
      }
    } catch (error) {
      response.writeHead(500);
      response.end(JSON.stringify({ error: error.message }));
    }
  });
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  base = `http://127.0.0.1:${server.address().port}`;
  async function run(packageRoot, state, action) {
    return await new Promise((resolve, reject) => {
      const worker = fork(import.meta.filename, ["child", packageRoot, base, action], {
        env: { ...process.env, OPENCLAW_STATE_DIR: path.join(stateRoot, state), OPENCLAW_NIX_MODE: "1" },
        stdio: ["ignore", "pipe", "pipe", "ipc"],
      });
      let result;
      let errors = "";
      const timer = setTimeout(() => { worker.kill(); reject(new Error(`packaged OAuth ${action} timed out`)); }, 30000);
      worker.on("message", (value) => { result = value; });
      worker.stderr.on("data", (chunk) => { errors += chunk; });
      worker.on("error", reject);
      worker.on("exit", (code) => {
        clearTimeout(timer);
        if (code === 0 && result) resolve(result);
        else reject(new Error(`packaged OAuth ${action} failed: ${errors}`));
      });
    });
  }
  try {
    if (baseline) {
      assert.equal((await run(baseline, "baseline", "login")).bound, false);
      seedStore("baseline", "unrelated-synthetic-row", () => ({ marker: "preserved" }));
      assert.equal((await run(baseline, "baseline", "refresh")).authorized, true);
      active = "foreign";
      const start = events.length;
      assert.equal((await run(baseline, "baseline", "foreign")).rejected, true);
      assert.equal(events.slice(start).some((event) => event.path.startsWith("/foreign/") && event.carriesCredential), false);
      console.log("Baseline gateway: issuer-less credentials refresh; existing foreign-refresh guard holds");
      active = "trusted";
    }
    await run(baseline ?? root, "upgrade", "login");
    seedStore("upgrade", "unrelated-synthetic-row", () => ({ marker: "preserved" }));
    if (!baseline) seedStore("upgrade", "synthetic-oauth-flow", (store) => {
      const clientInformation = { ...store.clientInformation };
      const tokens = { ...store.tokens };
      delete clientInformation.issuer;
      delete tokens.issuer;
      return { ...store, clientInformation, tokens, tokenExpiresAt: Date.now() + 600000 };
    });
    const legacyStart = events.length;
    assert.equal((await run(root, "upgrade", "read")).rejected, true);
    assert.equal((await run(root, "upgrade", "refresh")).rejected, true);
    assert.equal(events.slice(legacyStart).some((event) => event.carriesCredential), false);
    await run(root, "upgrade", "clear");
    assert.equal((await run(root, "upgrade", "login")).bound, true);
    assert.equal((await run(root, "upgrade", "refresh")).bound, true);
    active = "foreign";
    const foreignStart = events.length;
    assert.equal((await run(root, "upgrade", "foreign")).rejected, true);
    assert.equal(events.slice(foreignStart).some((event) => event.path.startsWith("/foreign/") && event.carriesCredential), false);
    console.log("Packaged OAuth + HTTP + SQLite: login, refresh, legacy upgrade/recovery, and foreign-issuer rejection passed");
  } finally {
    await new Promise((resolve) => server.close(resolve));
    fs.rmSync(stateRoot, { recursive: true, force: true });
  }
}

if (process.argv[2] === "child") {
  await child();
  process.disconnect();
}
else await main();

"""Stage0 only: install one authentic HM generation and observe its gateway."""

import json
import os
from pathlib import Path
import platform
import pwd
import re
import subprocess
import sys
import time


LABEL = "org.openclaw.nix.installed-baseline"
UNIT = "openclaw-installed-baseline.service"


def run(args, env, check=True):
    result = subprocess.run(
        [str(arg) for arg in args], env=env, text=True,
        stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=120,
    )
    print(result.stdout, end="", flush=True)
    print(result.stderr, end="", file=sys.stderr, flush=True)
    if check:
        result.check_returncode()
    return result


def prepare_home(home, username, global_state=Path("/nix/var/nix")):
    # Locked HM migrates/removes old global profiles, even with an isolated HOME.
    profiles = global_state / "profiles/per-user" / username
    roots = global_state / "gcroots/per-user" / username
    if list(profiles.glob("home-manager*")) or os.path.lexists(roots / "current-home"):
        raise RuntimeError("existing global Home Manager ownership; refusing activation")
    home.mkdir(mode=0o700)  # Existing or dangling homes are never reused/deleted.
    local_profiles = home / ".local/state/nix/profiles"
    local_profiles.mkdir(parents=True)
    (home / ".nix-profile").symlink_to(local_profiles / "profile")
    return local_profiles / "home-manager"


def install_generation(generation, profile, env):
    # Locked HM doSwitch sets the profile before activate --driver-version 1.
    run(["nix-env", "--profile", profile, "--set", generation], env)
    run([generation / "activate", "--driver-version", "1"], env)
    if profile.resolve(strict=True) != generation:
        raise RuntimeError("installed generation differs from built baseline")


def verify_systemd_unit(home, generation, env):
    unit = Path(".config/systemd/user") / UNIT
    expected = (generation / "home-files" / unit).resolve(strict=True)
    fragment = run([
        "systemctl", "--user", "show", UNIT, "-p", "FragmentPath", "--value",
    ], env).stdout.strip()
    if (
        not fragment
        or (home / unit).resolve(strict=True) != expected
        or Path(fragment).resolve(strict=True) != expected
    ):
        raise RuntimeError("systemd did not load the baseline generation's unit")
    print(json.dumps({"fragmentPath": fragment, "generatedUnit": str(expected)}), flush=True)


def service_state(darwin, env):
    if darwin:
        result = run(["launchctl", "print", f"gui/{os.getuid()}/{LABEL}"], env, False)
        if result.returncode:
            return 0
        runs = re.search(r"^\s*runs = (\d+)$", result.stdout, re.M)
        if runs and int(runs[1]) > 1:
            raise RuntimeError("baseline launchd service restarted")
        if re.search(r"last exit code = [1-9]|last terminating signal", result.stdout):
            raise RuntimeError("baseline launchd service exited")
        pid = re.search(r"^\s*pid = (\d+)$", result.stdout, re.M)
        return int(pid[1]) if pid else 0
    result = run([
        "systemctl", "--user", "show", UNIT, "-p", "MainPID",
        "-p", "NRestarts", "-p", "ActiveState", "-p", "Result",
    ], env)
    values = dict(line.split("=", 1) for line in result.stdout.splitlines() if "=" in line)
    if values["NRestarts"] != "0" or values["Result"] != "success":
        raise RuntimeError("baseline systemd service failed or restarted")
    if values["ActiveState"] == "failed":
        raise RuntimeError("baseline systemd service failed")
    return int(values["MainPID"])


def main():
    home, generation, bundle, node = map(Path, sys.argv[1:])
    generation, bundle, node = (path.resolve(strict=True) for path in (generation, bundle, node))
    if any(not str(path).startswith("/nix/store/") for path in (generation, bundle, node)):
        raise RuntimeError("baseline artifacts must be realized Nix store paths")
    darwin = platform.system() == "Darwin"
    expected_home = Path("/tmp/openclaw-installed-baseline" if darwin else "/home/baseline/qualification")
    username = pwd.getpwuid(os.getuid()).pw_name
    if home != expected_home or username != ("runner" if darwin else "baseline"):
        raise RuntimeError("probe requires its disposable runner user and HOME")
    env = {
        key: value for key, value in os.environ.items()
        if not key.startswith(("OPENCLAW_", "HOME_MANAGER_"))
        and key not in {"DRY_RUN", "SKIP_SANITY_CHECKS", "NIX_PROFILES"}
    }
    env.update(HOME=str(home), USER=username, LOGNAME=username)
    env.update(
        OPENCLAW_STATE_DIR=str(home / ".openclaw-baseline"),
        OPENCLAW_CONFIG_PATH=str(home / ".openclaw-baseline/openclaw.json"),
    )
    for name, suffix in {
        "XDG_STATE_HOME": ".local/state", "XDG_DATA_HOME": ".local/share",
        "XDG_CONFIG_HOME": ".config", "XDG_CACHE_HOME": ".cache",
    }.items():
        env[name] = str(home / suffix)
    if darwin and run(["launchctl", "print", f"gui/{os.getuid()}/{LABEL}"], env, False).returncode == 0:
        raise RuntimeError("qualification launchd label already exists")
    profile = prepare_home(home, username)
    phase = "activation"
    try:
        install_generation(generation, profile, env)
        executable = home / ".nix-profile/bin/openclaw"
        if executable.resolve(strict=True) != (bundle / "bin/openclaw").resolve(strict=True):
            raise RuntimeError("installed executable does not belong to the baseline bundle")
        print(json.dumps({
            "phase": "installed", "generation": str(generation),
            "profile": str(profile), "generationLink": os.readlink(profile),
            "executable": str(executable.resolve()), "bundle": str(bundle),
        }), flush=True)
        run([executable, "--version"], env)
        phase = "service-start"
        if not darwin:
            run(["systemctl", "--user", "daemon-reload"], env)
            verify_systemd_unit(home, generation, env)
            run(["systemctl", "--user", "start", UNIT], env)
        deadline = time.monotonic() + 90
        while time.monotonic() < deadline:
            pid = service_state(darwin, env)
            if pid:
                health = run([
                    executable, "gateway", "health", "--url", "ws://127.0.0.1:18997",
                    "--token", "installed-baseline-fixture-token", "--json", "--timeout", "3000",
                ], env, False)
                if health.returncode == 0 and json.loads(health.stdout).get("ok") is True:
                    break
            time.sleep(1)
        else:
            raise RuntimeError("baseline gateway did not become healthy")
        if service_state(darwin, env) != pid:
            raise RuntimeError("baseline gateway PID changed during health probe")
        if darwin:
            mappings = run(["lsof", "-a", "-p", str(pid), "-d", "txt", "-Fn"], env).stdout
            nodes = [Path(line[1:]) for line in mappings.splitlines() if line.startswith("n/nix/store/") and line.endswith("/bin/node")]
            if nodes != [node]:
                raise RuntimeError("gateway executable is not the locked Node runtime")
            actual_node = nodes[0]
        else:
            actual_node = Path(f"/proc/{pid}/exe").resolve(strict=True)
            if actual_node != node:
                raise RuntimeError("gateway executable is not the locked Node runtime")
        version = run([actual_node, "--version"], env).stdout.strip()
        if not version.startswith("v22."):
            raise RuntimeError(f"baseline runtime is not Node.js 22: {version}")
        print(json.dumps({
            "result": "PASS", "scope": "installed-baseline-only", "pid": pid,
            "node": str(actual_node), "nodeVersion": version, "health": json.loads(health.stdout),
            "acpx": "NOT_QUALIFIED: historical baseline, no discovery or session proof",
        }), flush=True)
    except Exception:
        print(f"BLOCKED stage0 phase={phase}; no fallback or transition attempted", flush=True)
        log = home / "gateway.log"
        if log.is_file():
            print(log.read_text()[-16000:], flush=True)
        raise
    finally:
        if darwin:
            run(["launchctl", "bootout", f"gui/{os.getuid()}/{LABEL}"], env, False)
        else:
            run(["systemctl", "--user", "stop", UNIT], env, False)


if __name__ == "__main__":
    main()

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const installer = path.join(import.meta.dirname, "openclaw-gateway-npm-install.sh");
const checker = path.join(import.meta.dirname, "check-package-contents.sh");
const pluginInstaller = path.join(import.meta.dirname, "runtime-plugin/install.mjs");
const legacyNames = ["hasown", "combined-stream"];
const acpxAliases = ["index.js", "register.runtime.js", "runtime-api.js", "setup-api.js"];

function put(root, name, text = "") {
  const file = path.join(root, name);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, text);
  return file;
}

function dependency(modules, name, marker, code) {
  const root = path.join(modules, name);
  put(root, "package.json", JSON.stringify({ name, version: `${marker}.0.0`, type: "commonjs", main: "index.cjs" }));
  put(root, "index.cjs", code ?? `module.exports = { marker: ${marker}, file: __filename };\n`);
  return root;
}

function snapshot(root) {
  const files = {};
  for (const name of fs.readdirSync(root, { recursive: true }).sort()) {
    const file = path.join(root, name);
    const stat = fs.lstatSync(file);
    if (!stat.isDirectory())
      files[name] = stat.isSymbolicLink() ? fs.readlinkSync(file) : fs.readFileSync(file).toString("hex");
  }
  return files;
}

function fixture(t, layout = "mixed") {
  const temp = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "openclaw-npm-output-")));
  t.after(() => fs.rmSync(temp, { recursive: true, force: true }));
  const build = path.join(temp, "build");
  const modules = path.join(build, "node_modules");
  const packageRoot = path.join(modules, "openclaw");
  const out = path.join(temp, "out");
  const root = path.join(out, "lib/openclaw");
  const away = path.join(temp, "away");
  const home = path.join(temp, "home");
  const acpx = path.join(temp, "acpx");
